using System;

namespace CampusNetHelper
{
    /// <summary>
    /// C9 识别用的字体模板库（自动生成，别手改 —— 改请改生成脚本）。
    ///
    /// ⚠️ 为什么是 .cs 而不是任务书写的 captchatemplates.bin：
    ///    项目硬约束是"绿色免安装单文件"。多一个 .bin 就是让用户拷两个文件，
    ///    直接违背约束。把数据编进 exe 功能等价，约束不破。
    ///
    /// 数据来源：用本机 GDI+（System.Drawing）渲染 A-Z 0-9 共 36 个字形。
    ///    选 GDI+ 而不是别的渲染器，是因为门户服务器就是 ASP.NET + System.Drawing，
    ///    同一个渲染器出来的字形，笔画粗细和抗锯齿才对得上。
    ///
    /// 存储方式：上面的模板数据先按下面的格式打包，再 **裸 deflate 压缩**
    ///    （zlib 的 wbits=-15，**不带** zlib 头与 Adler-32 尾），
    ///    最后 base64 成文本。压缩是必须的 —— 不压的话 .NET 的 UTF-16
    ///    字符串常量会把这 67.5KB 的数据撑成约 380KB 的 exe 增量。
    ///    ⚠️ 必须是**裸 deflate**：.NET Framework 4.x 的 DeflateStream 不吃
    ///       zlib 容器格式（那要 .NET 6+ 的 ZLibStream），喂错了会抛
    ///       InvalidDataException「块的长度与它的补集不匹配」。2026-10-03 踩过。
    ///
    /// 打包格式（小端）：
    ///    charIndex : byte   在 CHARSET 里的下标
    ///    h         : byte   行数
    ///    w         : byte   列数
    ///    rows      : h × uint，第 y 行一个位掩码，第 x 位 = 第 x 列
    ///
    /// 模板共 1152 个，覆盖 32 个字体配置。
    /// 实测（30 张真实样本，留出集 15 张）：字符准确率 76.7%，整图全对 33.3%。
    /// </summary>
    internal static class CaptchaTemplates
    {
        public const string Charset = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

        private const string B64 =
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "";



        private static byte[] _data;

        /// <summary>解出打包好的模板字节流（只解一次，之后缓存）。</summary>
        public static byte[] Data()
        {
            if (_data == null) _data = Convert.FromBase64String(B64);
            return _data;
        }
    }
}
